tool_input.command:
python3 -I -c "
import urllib.request, json
u='https://api.crossref.org/works?query.bibliographic=IntelliLight+reinforcement+learning+traffic+light+control&rows=2&select=title,author,container-title,issued,volume,issue,page,DOI'
try:
    d=json.load(urllib.request.urlopen(u, timeout=20))
    for it in d['message']['items']:
        print(it.get('title'), it.get('DOI'))
except Exception as e:
    print('ERR', type(e).__name__, e)
"

